        pts = [np.array([x, y, 0]) for x in np.arange(x_range[0], x_range[1] + 1e-06, step) for y in np.arange(y_range[0], y_range[1] + 1e-06, step)]
        top = max((np.linalg.norm(func(p)) for p in pts)) or 1
        for p in pts:
