def zero(function):

    @wraps(function)
    def wrapper(t, *args, **kwargs):
        if 0 <= t <= 1:
            return function(t, *args, **kwargs)
        else:
            return 0
    return wrapper

@zero
def inverse_smooth(t: float, inflection: float=10.0):
    new_t = 1 - t
    return smooth(new_t, inflection)

@zero
def inverse_linear(t: float, inflection: float=10.0):
    return 1 - t

